package escuela.personal.controller;
import escuela.personal.dto.*;
import escuela.personal.service.*;
import escuela.admin.dto.*;
import escuela.admin.support.MensajeErrorFormulario;
import escuela.common.exception.ReglaNegocioException;
import lombok.RequiredArgsConstructor;
import jakarta.validation.Valid;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.http.*;
import java.util.*;
import java.io.IOException;

@Controller @RequiredArgsConstructor @RequestMapping("/admin/prestamos")
public class PrestamoProgramadoController {
 private final PrestamoProgramadoService service;
 private static String origen(String x){return x!=null&&x.length()<2000&&(x.equals("/admin/prestamos")||x.startsWith("/admin/prestamos?"))&&!x.contains("\r")&&!x.contains("\n")?x:"/admin/prestamos";}
 private void base(Model m,String retorno){m.addAttribute("origen",origen(retorno));m.addAttribute("puedeAdministrar",service.permitido("PRESTAMO_ADMINISTRAR"));m.addAttribute("puedeEntregar",service.permitido("PRESTAMO_ADMINISTRAR"));m.addAttribute("puedeReprogramar",service.permitido("PRESTAMO_ADMINISTRAR"));m.addAttribute("hoy",service.hoy());}
 @GetMapping String listado(@ModelAttribute FiltroPrestamoPrograma filtro,Model m){base(m,null);m.addAttribute("filtro",filtro.normalizado());try{m.addAttribute("resultado",service.listar(filtro));}catch(ReglaNegocioException ex){m.addAttribute("errorOperacion",ex.getMessage());m.addAttribute("resultado",org.springframework.data.domain.Page.empty());}var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();var permisos=a.getAuthorities().stream().map(x->x.getAuthority()).collect(java.util.stream.Collectors.toSet());m.addAttribute("modulos",Arrays.stream(ModuloCatalogo.values()).filter(x->x.visibleCon(permisos)).toList());m.addAttribute("moduloActual",ModuloCatalogo.PRESTAMOS);return "admin/prestamos-programados";}
 @GetMapping("/nuevo") String nuevo(@RequestParam(required=false)String origen,@RequestParam(required=false)Long empleadoId,Model m){if(!service.permitido("PRESTAMO_ADMINISTRAR"))throw new org.springframework.security.access.AccessDeniedException("Se requiere administrar préstamos");var f=new PrestamoProgramaForm();f.setEmpleadoId(empleadoId);if(empleadoId!=null)f.setEmpleadoTexto(service.textoEmpleado(empleadoId));f.setInicio(service.hoy());return formulario(null,false,f,origen,m);}
 @GetMapping("/{id}/editar") String editar(@PathVariable Long id,@RequestParam(required=false)String origen,Model m){if(!service.permitido("PRESTAMO_ADMINISTRAR"))throw new org.springframework.security.access.AccessDeniedException("Se requiere administrar préstamos");return formulario(id,false,service.formulario(id,false),origen,m);}
 @GetMapping("/{id}/reprogramar") String reprogramar(@PathVariable Long id,@RequestParam(required=false)String origen,Model m){if(!service.permitido("PRESTAMO_ADMINISTRAR"))throw new org.springframework.security.access.AccessDeniedException("Se requiere reestructurar préstamos");return formulario(id,true,service.formulario(id,true),origen,m);}
 private String formulario(Long id,boolean reprogramar,PrestamoProgramaForm f,String origen,Model m){base(m,origen);m.addAttribute("form",f);m.addAttribute("registroId",id);m.addAttribute("reprogramar",reprogramar);m.addAttribute("titulo",reprogramar?"Reprogramar saldo pendiente":id==null?"Nuevo préstamo":"Editar borrador de préstamo");if(id!=null)m.addAttribute("registro",service.obtener(id));return "admin/prestamo-programa-form";}
 @PostMapping("/revisar") String revisar(@RequestParam(required=false)Long registroId,@RequestParam(defaultValue="false")boolean reprogramar,@RequestParam(required=false)String origen,@Valid @ModelAttribute("form")PrestamoProgramaForm f,BindingResult errores,Model m){if(!errores.hasErrors())try{var v=service.revisar(registroId,reprogramar,f);f.setSello(v.sello());m.addAttribute("revision",v);}catch(ReglaNegocioException ex){m.addAttribute("errorOperacion",ex.getMessage());}if(errores.hasErrors())m.addAttribute("errorOperacion","Revisa los campos señalados en rojo. No se guardó nada.");return formulario(registroId,reprogramar,f,origen,m);}
 @PostMapping("/guardar") String guardar(@RequestParam(required=false)Long registroId,@RequestParam(defaultValue="false")boolean reprogramar,@RequestParam(required=false)String origen,@Valid @ModelAttribute("form")PrestamoProgramaForm f,BindingResult errores,Model m,RedirectAttributes flash){if(!errores.hasErrors())try{Long id=service.guardar(registroId,reprogramar,f);flash.addFlashAttribute("mensaje",reprogramar?"Saldo reprogramado. No se entregó dinero ni se alteraron abonos anteriores.":"Préstamo guardado como borrador. Todavía no se entregó dinero.");return "redirect:/admin/prestamos/"+id+"?origen="+org.springframework.web.util.UriUtils.encode(origen(origen),java.nio.charset.StandardCharsets.UTF_8);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException ex){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));}if(errores.hasErrors())m.addAttribute("errorOperacion","Revisa los campos obligatorios; la captura permanece aquí.");return formulario(registroId,reprogramar,f,origen,m);}
 @PostMapping("/editar-captura") String editarCaptura(@RequestParam(required=false)Long registroId,@RequestParam(defaultValue="false")boolean reprogramar,@RequestParam(required=false)String origen,@ModelAttribute("form")PrestamoProgramaForm f,Model m){return formulario(registroId,reprogramar,f,origen,m);}
@GetMapping("/{id}") String detalle(@PathVariable Long id,@RequestParam(required=false)String origen,@RequestParam(required=false)Long planConsulta,Model m){base(m,origen);var r=service.obtener(id);m.addAttribute("registro",r);m.addAttribute("entregaRegistrada",service.entregaRegistrada(id));var calendario=service.cuotas(id,planConsulta);m.addAttribute("cuotas",calendario);m.addAttribute("cuotasPagadas",calendario.stream().filter(c->c.pagada()).count());m.addAttribute("proximaCuota",calendario.stream().filter(c->!c.pagada()).findFirst().orElse(null));m.addAttribute("requiereReprogramar",service.requiereReprogramar(id));m.addAttribute("planConsulta",planConsulta==null&&r.plan()!=null?r.plan().id():planConsulta);m.addAttribute("historial",service.historial(id));m.addAttribute("abonos",service.abonos(id));m.addAttribute("gestiones",service.gestiones(id));if(!m.containsAttribute("entregaForm")){var f=new EntregarPrestamoForm();f.setVersion(r.version());m.addAttribute("entregaForm",f);}return "admin/prestamo-programa-detalle";}
 @PostMapping("/{id}/revisar-entrega") String revisarEntrega(@PathVariable Long id,@RequestParam(required=false)String origen,@ModelAttribute("entregaForm")EntregarPrestamoForm f,Model m){try{m.addAttribute("revisionEntrega",service.revisarEntrega(id,f));}catch(ReglaNegocioException ex){m.addAttribute("errorOperacion",ex.getMessage());}m.addAttribute("tabInicial","gestion");m.addAttribute("gestionTab","entrega");return detalle(id,origen,null,m);}
 @PostMapping("/{id}/entregar") String entregar(@PathVariable Long id,@RequestParam(required=false)String origen,@RequestParam String sello,@ModelAttribute("entregaForm")EntregarPrestamoForm f,Model m){try{service.entregar(id,f,sello);m.addAttribute("mensaje","Entrega registrada una sola vez. Los descuentos se abonarán al liquidar la nómina.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException ex){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));}m.addAttribute("tabInicial","gestion");m.addAttribute("gestionTab","entrega");return detalle(id,origen,null,m);}
 @PostMapping("/{id}/editar-entrega") String editarEntrega(@PathVariable Long id,@RequestParam(required=false)String origen,@ModelAttribute("entregaForm")EntregarPrestamoForm f,Model m){if(!service.permitido("PRESTAMO_ADMINISTRAR"))throw new org.springframework.security.access.AccessDeniedException("Se requiere entregar préstamos");m.addAttribute("tabInicial","gestion");m.addAttribute("gestionTab","entrega");return detalle(id,origen,null,m);}
 @PostMapping("/{id}/cancelar") String cancelar(@PathVariable Long id,@RequestParam Long version,@RequestParam String motivo,@RequestParam(required=false)String origen,Model m){try{service.cancelarBorrador(id,version,motivo);m.addAttribute("mensaje","Borrador cancelado sin mover dinero.");}catch(ReglaNegocioException ex){m.addAttribute("errorOperacion",ex.getMessage());m.addAttribute("motivoCancelacion",motivo);}m.addAttribute("tabInicial","gestion");m.addAttribute("gestionTab","cancelar");return detalle(id,origen,null,m);}
 @GetMapping("/empleados/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> empleados(@RequestParam(defaultValue="")String q){return opciones(service.buscarEmpleados(q));}
 @GetMapping("/conceptos/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> conceptos(@RequestParam(defaultValue="")String q){return opciones(service.conceptos(q));}
 @GetMapping("/concepto") @ResponseBody ResponseEntity<?> concepto(@RequestParam Long conceptoId){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.concepto(conceptoId));}
 @GetMapping("/cuentas/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> cuentas(@RequestParam(defaultValue="")String q){return opciones(service.cuentas(q));}
 @GetMapping("/motivos/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> motivos(@RequestParam(defaultValue="")String q){return opciones(service.motivos(q));}
 private ResponseEntity<ResultadoAutocompletado> opciones(List<OpcionAutocompletado> l){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(l.stream().limit(10).toList(),l.size()>10));}
 @GetMapping("/excel") void excel(@ModelAttribute FiltroPrestamoPrograma filtro,HttpServletResponse response)throws IOException{service.listar(filtro);response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename=prestamos.xlsx");response.setHeader("Cache-Control","no-store");try(var wb=new org.apache.poi.xssf.streaming.SXSSFWorkbook(100)){try{var sh=wb.createSheet("Préstamos");String[] cab={"Préstamo","Empleado","Concepto","Principal solicitado","Capital pendiente","Interés pendiente","Total pendiente","Moneda","Estado","Frecuencia","Primera cuota","Última cuota"};var head=sh.createRow(0);for(int i=0;i<cab.length;i++){head.createCell(i).setCellValue(cab[i]);sh.setColumnWidth(i,28*256);}int row=1,page=0;org.springframework.data.domain.Page<PrestamoProgramadoService.Registro> bloque;do{bloque=service.listar(filtro.normalizado().pagina(page++));for(var r:bloque){Object[] vals={r.folio(),r.codigo()+" · "+r.empleado(),r.concepto(),r.principal(),r.capitalPendiente(),r.interesPendiente(),r.saldo(),r.moneda(),r.estado(),r.plan()==null?"Anterior":r.plan().frecuencia(),r.plan()==null?"":r.plan().inicio().toString(),r.plan()==null?"":r.plan().fin().toString()};var rr=sh.createRow(row++);for(int i=0;i<vals.length;i++){var cell=rr.createCell(i);if(vals[i] instanceof Number n)cell.setCellValue(n.doubleValue());else cell.setCellValue(vals[i].toString());}}}while(bloque.hasNext());sh.createFreezePane(0,1);wb.write(response.getOutputStream());}finally{wb.dispose();}}}
}
